from abc import ABC, abstractmethod


class DataAdapter(ABC):
    """Interface for adapting data items to a normalized form."""

    @abstractmethod
    def accepts(self, item) -> bool:
        """Return True if this item should be processed."""
        ...

    @abstractmethod
    def adapt(self, item):
        """Transform the item into its normalized form."""
        ...


class PassthroughAdapter(DataAdapter):
    """Default adapter that accepts everything and passes items through."""

    def accepts(self, item) -> bool:
        return True

    def adapt(self, item):
        return item


class FilterAdapter(DataAdapter):
    """Adapter that filters items based on a predicate."""

    def __init__(self, predicate, delegate: DataAdapter | None = None):
        self.predicate = predicate
        self.delegate = delegate or PassthroughAdapter()

    def accepts(self, item) -> bool:
        return self.predicate(item) and self.delegate.accepts(item)

    def adapt(self, item):
        return self.delegate.adapt(item)


class TransformAdapter(DataAdapter):
    """Adapter that transforms items using a mapping function."""

    def __init__(self, transform_fn, delegate: DataAdapter | None = None):
        self.transform_fn = transform_fn
        self.delegate = delegate or PassthroughAdapter()

    def accepts(self, item) -> bool:
        return self.delegate.accepts(item)

    def adapt(self, item):
        return self.transform_fn(self.delegate.adapt(item))


class DataProcessor:
    """Processes data through a composable adapter chain."""

    def __init__(self, adapter: DataAdapter | None = None):
        self.adapter = adapter or PassthroughAdapter()

    def process(self, data):
        return [
            self.adapter.adapt(item)
            for item in data
            if self.adapter.accepts(item)
        ]

from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Callable, Sequence


class DataAdapter(ABC):
    """Target interface: adapts external data into normalized items."""

    @abstractmethod
    def accepts(self, item: Any) -> bool:
        """Filter gate — return False to skip this item."""
        ...

    @abstractmethod
    def adapt(self, item: Any) -> Any:
        """Transform item into normalized form."""
        ...


class PassthroughAdapter(DataAdapter):
    """Identity adapter — accepts everything, no transformation."""

    def accepts(self, item: Any) -> bool:
        return True

    def adapt(self, item: Any) -> Any:
        return item


class PredicateAdapter(DataAdapter):
    """Adapter that filters via a predicate, delegating transform downstream."""

    def __init__(self, predicate: Callable[[Any], bool], delegate: DataAdapter | None = None):
        self.predicate = predicate
        self.delegate = delegate or PassthroughAdapter()

    def accepts(self, item: Any) -> bool:
        return self.predicate(item) and self.delegate.accepts(item)

    def adapt(self, item: Any) -> Any:
        return self.delegate.adapt(item)


class TransformAdapter(DataAdapter):
    """Adapter that maps items through a function, delegating upstream."""

    def __init__(self, fn: Callable[[Any], Any], delegate: DataAdapter | None = None):
        self.fn = fn
        self.delegate = delegate or PassthroughAdapter()

    def accepts(self, item: Any) -> bool:
        return self.delegate.accepts(item)

    def adapt(self, item: Any) -> Any:
        return self.fn(self.delegate.adapt(item))


class DataProcessor:
    """Runs items through an adapter chain."""

    def __init__(self, adapter: DataAdapter | None = None):
        self.adapter = adapter or PassthroughAdapter()

    def process(self, data: list[Any]) -> list[Any]:
        return [
            self.adapter.adapt(item)
            for item in data
            if self.adapter.accepts(item)
        ]


def from_config(config: dict[str, Any]) -> DataProcessor:
    """Build a processor from a config dict — drop-in replacement for the original."""
    adapter: DataAdapter = PassthroughAdapter()
    if config.get("transform"):
        adapter = TransformAdapter(config["transform"], adapter)
    if config.get("filter"):
        adapter = PredicateAdapter(config["filter"], adapter)
    return DataProcessor(adapter)

